"css": "\n:scope:not([data-settled]), :scope:not([data-settled]) * { transition: none !important; }\n\n:scope:not([data-ready=\"true\"]) .ys-tablist { display: none; }\n:scope[data-ready=\"true\"] .ys-panel[data-on=\"false\"] { display: none; }\n.ys-tab { cursor: pointer; transition: background-color 180ms cubic-bezier(0.16, 1, 0.3, 1), color 180ms cubic-bezier(0.16, 1, 0.3, 1), transform 120ms cubic-bezier(0.16, 1, 0.3, 1); }\n.ys-tab + .ys-tab { border-left: 2px solid var(--d10184c8-299f-44cc-9cc4-6c157ab82ff9); }\n.ys-tab[aria-selected=\"true\"] { background-color: var(--d10184c8-299f-44cc-9cc4-6c157ab82ff9) !important; color: var(--61b9a0dd-bc66-4d7f-8665-a7ecc186a2b9) !important; }\n.ys-tab:hover:not([aria-selected=\"true\"]) { background-color: var(--5c17a78e-b9f8-4df9-92cd-d63edc1c3ecd); }\n.ys-tab:active { transform: translateY(1px); }\n.ys-tab:focus-visible { z-index: 1; outline: 3px solid var(--d9039d0b-819d-46c0-955a-c724d9bf8417); outline-offset: 4px; }\n.ys-row { transition: background-color 180ms cubic-bezier(0.16, 1, 0.3, 1), color 180ms cubic-bezier(0.16, 1, 0.3, 1), transform 120ms cubic-bezier(0.16, 1, 0.3, 1); }\n.ys-row-bar { transition: background-color 180ms cubic-bezier(0.16, 1, 0.3, 1); }\n.ys-row:hover, .ys-row:focus-visible { background-color: var(--d10184c8-299f-44cc-9cc4-6c157ab82ff9); color: var(--61b9a0dd-bc66-4d7f-8665-a7ecc186a2b9); --ys-track: color-mix(in oklab, var(--61b9a0dd-bc66-4d7f-8665-a7ecc186a2b9) 35%, transparent); }\n.ys-row:hover .ys-row-bar, .ys-row:focus-visible .ys-row-bar { background-color: var(--ea5b8c24-d2be-418f-87fc-5b135840543d); }\n.ys-row:active { transform: translateY(1px); }\n.ys-row:focus-visible { outline: 3px solid var(--d9039d0b-819d-46c0-955a-c724d9bf8417); outline-offset: 2px; }\n.ys-row[data-flat=\"true\"] { grid-template-columns: minmax(0, 1fr) auto !important; }\n.ys-row[data-flat=\"true\"] .ys-track { display: none !important; }\n@media (prefers-reduced-motion: reduce) { .ys-tab, .ys-row, .ys-row-bar { transition: none; } }\n",
"js": "\nconst live = typeof window !== \"undefined\";\nconst root = this;\nconst tabs = Array.from(root.querySelectorAll(\".ys-tab\"));\nconst panels = Array.from(root.querySelectorAll(\".ys-panel\"));\n// rows of other kinds are hidden at once: no fade, no stagger\nconst select = (i, focus) => {\n  tabs.forEach((tab, k) => {\n    const on = k === i;\n    tab.setAttribute(\"aria-selected\", on ? \"true\" : \"false\");\n    tab.setAttribute(\"tabindex\", on ? \"0\" : \"-1\");\n    if (panels[k]) { panels[k].dataset.on = on ? \"true\" : \"false\"; panels[k].hidden = !on; }\n  });\n  if (focus && tabs[i]) tabs[i].focus();\n};\nselect(0, false);\nroot.dataset.ready = \"true\";\nif (!live) return;\n\nconst settle = () => requestAnimationFrame(() => requestAnimationFrame(() => { root.dataset.settled = \"\"; }));\nif (document.readyState === \"loading\") document.addEventListener(\"DOMContentLoaded\", settle, { once: true });\nelse settle();\nconst unsettle = () => { document.removeEventListener(\"DOMContentLoaded\", settle); delete root.dataset.settled; };\n\nconst cleanups = [unsettle];\nconst on = (el, type, fn) => { el.addEventListener(type, fn); cleanups.push(() => el.removeEventListener(type, fn)); };\ntabs.forEach((tab, i) => {\n  on(tab, \"click\", () => select(i, false));\n  on(tab, \"keydown\", (event) => {\n    const n = tabs.length;\n    const moves = { ArrowRight: (i + 1) % n, ArrowLeft: (i - 1 + n) % n, Home: 0, End: n - 1 };\n    if (!(event.key in moves)) return;\n    event.preventDefault();\n    select(moves[event.key], true);\n  });\n});\nreturn () => cleanups.forEach((fn) => fn());\n"
},
